70	  function undoEnable(root,input){keys(input,['enable_id','author_evidence']);if(!UUID.test(input.enable_id??''))fail('TOOL_INPUT_INVALID','enable_id无效');return withLock(root,()=>{
71	    const p=project(root),id=input.enable_id,dir=`.writer/tool-enables/${id}`,record=json(safe(p.root,dir+'/enable.json')),before=read(p.root,dir+'/before-state.bin'),current=digest(p.root,'.writer/state.json');
72	    if(hash(before)!==record.before_sha256)fail('TOOL_CONTROL_CORRUPT','启用备份损坏');if(exists(p.root,dir+'/undone.json')&&current===record.before_sha256)return {ok:true,unchanged:true,schema_version:5};
73	    if(p.state.schema_version!==6||control(p.state).generation!==0||p.state.tool_control.enable_id!==id||current!==record.after_sha256)fail('TOOL_ROLLBACK_UNSAFE','启用后已有业务变化，不能回填旧state');cleanSessions(p.root);external(p.root);const a=proof(p.root,input.author_evidence);io.storeBytes(p.root,a.evidence.frozen_ref,a.bytes,!exists(p.root,a.evidence.frozen_ref));io.metadata(p.root,dir+'/undo-proof.json',{evidence:a.evidence},!exists(p.root,dir+'/undo-proof.json'));io.storeBytes(p.root,'.writer/state.json',before);io.metadata(p.root,dir+'/undone.json',{state_sha256:record.before_sha256});seen.delete(p.root);return {ok:true,schema_version:5,revision:JSON.parse(before).revision,tool_unchanged:true};
74	  });}
