84	    if(hash(JSON.stringify(tx.protection))!==tx.protection_sha256)fail('TOOL_TRANSACTION_CORRUPT','作品保护清单损坏');
85	    const seen=new Set();for(const [i,r]of tx.plan.entries()){
86	      if(seen.has(r.file)||!(r.file.startsWith('.writer/tool/')||r.file==='.writer/state.json'||/^\.writer\/objects\/(?:[a-f0-9-]+\.json|[a-f0-9]{64}\.txt)$/.test(r.file)||WORK_GUIDES.map(n=>'docs/'+n).includes(r.file)))fail('TOOL_TRANSACTION_CORRUPT','工具事务路径越界或重复');seen.add(r.file);safe(root,r.file);
87	      for(const side of ['old','new']){const expected=side==='old'?r.before:r.after;if(expected===null){if(side==='new')fail('TOOL_TRANSACTION_CORRUPT','本批不删除工具文件');continue;}const ref=`.writer/transactions/${tx.id}/${side}/${i}.bin`;if(r[side+'_ref']!==ref||digest(root,ref)!==expected)fail('TOOL_TRANSACTION_CORRUPT','工具旧/新备份损坏');}
88	    }
